// Single-model test proposal: all limits, revisions and outcomes are fixtures.
const testDialog=document.createElement('dialog');testDialog.id='test-preview-dialog';testDialog.setAttribute('aria-labelledby','test-preview-title');$('#repomesh-rooms-prototype').append(testDialog);
const testRecords=new Map();let testView=null,testSequence=0;
const testSnapshotKey=(providerId,version,modelId)=>JSON.stringify([providerId,version,modelId]);
const testKey=i=>testSnapshotKey(selected,draft.version,draft.models[i]?.id);
const testLatest=key=>Array.from(testRecords.values()).reverse().find(t=>t.snapshotKey===key);
const testLabels={untested:'未测试',queued:'测试已登记',running:'本次测试中',unknown:'本次结果未知',passed:'本次测试通过',failed:'本次测试失败',rejected:'本次未测试'};
function testObservation(snapshotKey){const record=testLatest(snapshotKey)||null;return {record,label:testLabels[record?.stage||'untested']};}
const testButton=(label,action,primary=false,disabled=false)=>`<button type="button" data-test-preview="${action}" class="${primary?'primary':'outline'}" ${disabled?'disabled':''}>${label}</button>`;
function openTest(i){const outstanding=Array.from(testRecords.values()).find(t=>['queued','running','unknown'].includes(t.stage)&&!t.closed);if(outstanding){testView=outstanding;renderTest();if(!testDialog.open)testDialog.showModal();return;}if(dirty||pending||!draft.models[i])return;const key=testKey(i),old=testLatest(key);testView=old&&!old.closed&&['queued','running','unknown'].includes(old.stage)?old:{key:'test-'+(++testSequence),snapshotKey:key,index:i,provider:draft.name,version:draft.version,model:draft.models[i].id,maxOutput:Math.min(16,Number(draft.models[i].max)||16),stage:'preview',consent:false,budgetKnown:true};renderTest();if(!testDialog.open)testDialog.showModal();}
function closeTest(){testDialog.close();renderParts();joined.report('models','models',null);}
function renderTest(){const t=testView;let actions='',status='';
if(t.stage==='preview'){status=`<label class="test-consent"><input type="checkbox" id="test-charge-consent" ${t.consent?'checked':''}>我了解本次测试可能产生供应商费用</label>`;actions=testButton('取消','close')+testButton('确认并开始测试','submit',true,!t.consent||!t.budgetKnown);}
else{status=`<div class="test-result" role="status"><strong>${({queued:'测试已登记，等待开始',running:'正在测试这个模型',unknown:'本次测试结果待确认',passed:'本次测试通过',failed:'本次模型访问被拒绝',rejected:'本次未发出测试'})[t.stage]}</strong><p>${t.stage==='unknown'&&t.closed?'运维已证明原发送者失去调用能力；结果仍未知，次数按已消费保留。可另行确认新测试（此处仅演示）。':t.stage==='unknown'?'暂不再次发起测试，避免重复调用和收费。':t.stage==='passed'?'只说明这个模型的本次探测通过，不代表任务运行就绪。':t.stage==='failed'?'请检查供应商的模型访问资格；不能将全部失败归因为密钥错误。':t.stage==='queued'?'登记成功不等于模型测试通过。':'只观察本次固定快照。'}</p>${t.queried?'<small>样例查询未取得新结果，当前状态保持。</small>':''}</div>`;actions=testButton('稍后查看','close')+(['queued','running','unknown'].includes(t.stage)&&!t.closed?testButton('查询本次结果','query',true):'');}
const controls=t.stage==='preview'?testButton(t.budgetKnown?'模拟次数额度未知':'恢复预览样例','price'):['queued','running','unknown'].includes(t.stage)?(t.stage==='queued'?testButton('模拟调用开始','running'):'')+testButton('模拟结果未知','unknown')+testButton('模拟取得成功依据','passed')+testButton('模拟明确访问拒绝','failed')+(t.stage==='unknown'&&!t.closed?testButton('模拟运维核查关闭','close-unknown'):''):'';
testDialog.innerHTML=`<div class="modalhead"><h2 id="test-preview-title">${t.stage==='preview'?'测试前确认':'单模型测试结果'}</h2><button type="button" data-test-preview="close" aria-label="关闭测试弹窗">×</button></div><div class="modalbody"><p class="key-prototype">待审原型 · 不发送请求，不产生费用</p><div class="key-current"><span>供应商</span><strong>${esc(t.provider)}</strong><span>模型</span><strong>${esc(t.model)}</strong><span>固定快照</span><strong>v${t.version} · 密钥版本已绑定（样例）</strong><span>测试内容</span><strong>一次简短文本响应</strong></div><div class="key-info">${t.budgetKnown?`${t.stage==='preview'?'将预留 1 次测试请求':t.stage==='queued'?'已预留 1 次测试请求':'已计入 1 次请求消耗，费用仍以供应商为准'}（候选）<br>最多输出 ${t.maxOutput} Token · 等待上限 30 秒（候选）<br>供应商可能收费，次数限制不代表金额上限。`:'尚未取得有效次数额度，暂不能确认测试。'}</div>${status}<details class="key-tools" open><summary>原型场景</summary><div>${controls}</div></details></div><div class="modalfoot">${actions}</div>`;joined.report('models','model-test','单模型测试 · 费用确认与未知恢复待审');}
document.addEventListener('click',e=>{const original=e.target.closest('[data-original-test]');if(original){testView=Array.from(testRecords.values())[Number(original.dataset.originalTest)];renderTest();testDialog.showModal();return;}const b=e.target.closest('#models [data-action="test"]');if(b){e.preventDefault();e.stopImmediatePropagation();if(!b.disabled)openTest(Number(b.dataset.index));return;}const a=e.target.closest('[data-test-preview]')?.dataset.testPreview;if(!a)return;e.preventDefault();e.stopImmediatePropagation();if(a==='close'){closeTest();return;}const t=testView;if(a==='close-unknown'&&t.stage==='unknown'){t.closed=true;t.queried=false;}if(a==='price')t.budgetKnown=!t.budgetKnown;if(a==='submit'&&t.stage==='preview'&&t.consent&&t.budgetKnown){t.stage='queued';testRecords.set(t.key,t);}if(['running','unknown','passed','failed'].includes(a)&&t.stage!=='preview'){t.stage=a;t.queried=false;testRecords.set(t.key,t);}if(a==='query')t.queried=true;renderTest();renderParts();},true);
testDialog.addEventListener('change',e=>{if(e.target.id==='test-charge-consent'){testView.consent=e.target.checked;renderTest();}});testDialog.addEventListener('cancel',e=>{e.preventDefault();closeTest();});
const testResume=document.createElement('div');testResume.className='key-info';$('#models').before(testResume);
const testParts=renderParts;renderParts=function(){testParts();testResume.innerHTML=Array.from(testRecords.values()).map((t,i)=>`<div>原测试 ${esc(t.key)} · ${esc(t.provider)} / ${esc(t.model)} · v${t.version} <button type="button" data-original-test="${i}">查看原结果${t.closed&&t.stage==='unknown'?'（核查已关闭，结果未知）':''}</button></div>`).join('');testResume.hidden=!testRecords.size;draft.models.forEach((m,i)=>{const observation=testObservation(testKey(i)),t=observation.record;const row=$('#models').children[i];row.querySelector('.modelactions>span').textContent=dirty?'修改后需重新测试':observation.label;if(!t){const outstanding=Array.from(testRecords.values()).some(x=>['queued','running','unknown'].includes(x.stage)&&!x.closed);if(outstanding)row.querySelector('[data-action="test"]').textContent='先查询待核测试';return;}const button=row.querySelector('[data-action="test"]');button.textContent=['queued','running','unknown'].includes(t.stage)?'查询本次测试':'测试';});};
const testNavigate=window.joinedAPI.navigate;window.joinedAPI.navigate=function(route){testNavigate(route);if(route==='model-test')openTest(0);};
$('#test-result').closest('label').hidden=true;
const testCss=document.createElement('style');testCss.textContent='#repomesh-rooms-prototype .test-consent{display:flex;align-items:flex-start;gap:10px;font-size:13px;margin:18px 0}#repomesh-rooms-prototype .test-consent input{width:auto;margin:5px 0}#repomesh-rooms-prototype .test-result{border-top:1px solid #444;margin-top:16px;padding:16px 0;font-size:13px}#repomesh-rooms-prototype .test-result p{font-size:12px;color:#aaa}#repomesh-rooms-prototype #test-preview-dialog{width:min(620px,calc(100vw - 24px))}';document.head.append(testCss);
